const tiers={low:{title:'自动检查，定期抽查。',scope:'已核实的文化活动、人物背景，以及稳定的历史信息。',rule:'通过来源与事实一致性检查后可自动回答，并接受定期人工抽查。',color:'#e4eade'},medium:{title:'核查条件，异常复核。',scope:'教育政策、民生补贴、复杂政策，以及多篇报道综合。',rule:'重点核查资格、金额、期限及适用范围。发现来源冲突、异常回答或用户投诉时，转交编辑复核。',color:'#eee5d8'},high:{title:'人工审核优先。',scope:'重大灾害、公共安全、选举、严重指控及可能直接影响公众行动的信息。',rule:'原则上仅提供预先审核的事实性说明，或经指定编辑批准的回答。缺少可靠依据时，不得输出确定性结论。',color:'#e7e2ee'}};
const tabs=[...document.querySelectorAll('[data-tier]')],panel=document.querySelector('#tier-panel');function setTier(button){const t=tiers[button.dataset.tier];tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1});panel.setAttribute('aria-labelledby',button.id);panel.style.background=t.color;panel.innerHTML=`<div><small>适用场景</small><p>${t.scope}</p></div><div><h4>${t.title}</h4><p>${t.rule}</p></div>`}tabs.forEach((b,i)=>{b.addEventListener('click',()=>setTier(b));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%3;if(e.key==='ArrowLeft')n=(i+2)%3;if(e.key==='Home')n=0;if(e.key==='End')n=2;if(n!==undefined){e.preventDefault();tabs[n].focus();setTier(tabs[n])}})});setTier(tabs[0]);
const refs=[['BBC','Editorial Guidelines · Accuracy','https://www.bbc.co.uk/editorialguidelines/guidelines/accuracy/guidelines'],['Reuters','Journalistic standards','https://reutersagency.com/about/standards-values/'],['EBU & BBC · 2025','News integrity in AI assistants: Toolkit','https://www.ebu.ch/files/live/sites/ebu/files/Publications/MIS/open/EBU-MIS-BBC_News_Integrity_in_AI_Assistants_Toolkit_2025.pdf'],['Associated Press · 2026','AP updates newsroom standards for artificial intelligence','https://www.ap.org/the-definitive-source/announcements/ap-updates-newsroom-standards-for-artificial-intelligence/'],['Chicago Public Media · 2026','Newsroom acceptable use of AI policy','https://www.wbez.org/ai-policy'],['Poynter Institute · 2025','Template for a public newsroom generative AI policy','https://www.poynter.org/wp-content/uploads/2025/06/public_ai_ethics_guidelines.pdf'],['国家互联网信息办公室等 · 2023','生成式人工智能服务管理暂行办法','https://www.cac.gov.cn/2023-07/13/c_1690898327029107.htm'],['国家互联网信息办公室等 · 2026','智能体规范应用与创新发展实施意见','https://www.cac.gov.cn/2026-05/08/c_1779979789523320.htm'],['湖南日报 · 2025','新湖南客户端全线产品接入 DeepSeek','https://www.peopleapp.com/column/30048271218-500006094325'],['湖南日报 · 2026','新湖南客户端 13.0 上线','https://www.hunantoday.cn/news/xhn/202608/33487855.html']];document.querySelector('#reference-list').innerHTML=refs.map(([name,title,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer"><span>${name}<small>${title}</small></span><span aria-hidden="true">↗</span></a>`).join('');
const navLinks=[...document.querySelectorAll('nav a')];const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-15% 0px -65% 0px'});['background','risk','policy','effect'].forEach(id=>observer.observe(document.getElementById(id)));
